class G:
 def __init__(self):self.nodes={};self.edges=[]
 def n(self,i,label,shape='action',group=None):self.nodes[i]=(label,shape,group)
 def e(self,a,b,label='',arrow='-->'):self.edges.append((a,b,label,arrow))
 def code(self):
  out='flowchart TB\n'
  for j,group in enumerate(dict.fromkeys(n[2] for n in self.nodes.values())):
   if group:out+='subgraph group'+str(j)+'["'+group+'"]\n'
   for i,(label,shape,g) in self.nodes.items():
    if g!=group:continue
    s=label.replace('"','&quot;').replace('<','&lt;').replace('>','&gt;') or '#160;';out+=i+{'box':'["'+s+'"]','action':'(["'+s+'"])','decision':'{"'+s+'"}','start':'(("#160;"))','end':'((("#160;")))'}[shape]+'\n'
   if group:out+='end\n'
  for a,b,l,arrow in self.edges:out+=a+' '+arrow+('|"'+l.replace('<','&lt;').replace('>','&gt;')+'"|' if l else '')+' '+b+'\n'
  for i,(_,shape,_) in self.nodes.items():
   if shape=='start':out+='style '+i+' fill:#333,stroke:#333\n'
  return out

